import React from 'react';

import { Link } from 'react-router-dom';

import OneArticleBody from '@apps/Articles/components/OneArticleBody';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingArticleById } from '../@services/hikingArticles.service';
import { IHikingData } from '../@types/hiking.types';
import { IHikingArticleWithText } from '../@types/hikingArticles.types';

interface IHikingArticleOnePageProps {
  id_hiking: number;
  id_hiking_article: number;
}

const HikingArticleOnePage: React.FC<IHikingArticleOnePageProps> = ({
  id_hiking,
  id_hiking_article,
}) => {
  const [data, setData] = React.useState<IHikingArticleWithText | null>(null);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setIsErr] = React.useState<Error>();

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const ha = await getHikingArticleById(id_hiking_article, id_hiking);
        setData(ha);
      } catch (error) {
        setIsErr(err as Error);
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_hiking, id_hiking_article]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData) {
    return null;
  }
  if (!data) {
    return null;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          {
            href: `/hiking/${id_hiking}/articles`,
            text: 'Статьи',
          },
          {
            href: `/hiking/${id_hiking}/articles/${id_hiking_article}`,
            text: data.article.name,
            active: true,
          },
        ]}
      />
      <PageHeader title={data.article.name}>
        <Link to={`/articles/${data.article.id}`}>{data.article.name}</Link>
      </PageHeader>
      <article>
        <OneArticleBody text={data.article.text} />
      </article>
    </PohContainer>
  );
};

export default HikingArticleOnePage;
